for eid in [1,2,8,10,11,12]:
    try:
        df = pd.read_csv(globals()[f"experiment_{eid}_csv"])
        cols = [c for c in df.columns if df[c].dtype!=object]
        print(f"--- exp {eid} n={len(df)}")
        print(df[cols].mean().round(2).to_dict())
    except Exception as e:
        print(eid, "err", e)

